const projects=[
 ['flip','AI 变脸照','让同一张照片被模型读成另一种意思','https://jingsong-wang.github.io/ai-flip-photo/'],
 ['sticker','AI 贴纸挑战','用文字贴纸挑战视觉识别','https://jingsong-wang.github.io/sticker-challenge/'],
 ['reward','AI 打工翻车记','改变奖励，观察机器人的行为','https://jingsong-wang.github.io/reward-lab/'],
 ['fly','FLYLAB 数字果蝇','在虚拟培养皿里探索神经回路','https://jingsong-wang.github.io/fruit-fly/brain/']
];
class LabNavigation extends HTMLElement{
 connectedCallback(){if(this.shadowRoot)return;const root=this.attachShadow({mode:'open'}),current=this.getAttribute('current'),page=this.getAttribute('page');
 root.innerHTML=`<style>
 :host{display:block;position:relative;z-index:40;font:12px/1.5 -apple-system,BlinkMacSystemFont,'Segoe UI','Microsoft YaHei',sans-serif;--nav-bg:#fcfbf7;--nav-ink:#30362c;--nav-muted:#747c69;--nav-line:#d8dccf;--nav-hover:#edf0e5;--nav-accent:#cf472c;color:var(--nav-ink)}
 :host([theme=dark]){--nav-bg:#18211c;--nav-ink:#edf3e4;--nav-muted:#a2b09b;--nav-line:#394639;--nav-hover:#2a372b;--nav-accent:#bef48c}
 *{box-sizing:border-box}nav{display:flex;align-items:center;justify-content:flex-end;gap:7px}a{color:inherit;text-decoration:none}button,summary{font:inherit;color:inherit;cursor:pointer}a,summary{touch-action:manipulation}nav>.home,summary{padding:9px 11px;white-space:nowrap;border:1px solid var(--nav-line);border-radius:6px;background:var(--nav-bg);list-style:none}summary::-webkit-details-marker{display:none}summary:after{content:'⌄';margin-left:7px;color:var(--nav-muted)}summary.info:after{display:none}nav>.home:hover,summary:hover,details[open]>summary{background:var(--nav-hover)}details{position:relative}a:focus-visible,summary:focus-visible{outline:2px solid var(--nav-accent);outline-offset:3px}.panel{position:absolute;right:0;top:calc(100% + 10px);width:min(324px,calc(100vw - 32px));background:var(--nav-bg);border:1px solid var(--nav-line);border-radius:10px;box-shadow:0 16px 48px #0003;padding:10px}.label{padding:6px 10px 9px;color:var(--nav-muted);font-size:10px;letter-spacing:1px}.project{display:block;padding:11px 10px;border-radius:6px}.project:hover,.project[aria-current]{background:var(--nav-hover)}.title{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:13px;font-weight:600}.project small{display:block;color:var(--nav-muted);font-size:10px;margin-top:4px}.current{font-size:9px;color:var(--nav-accent);font-weight:500}.extras{border-top:1px solid var(--nav-line);margin:8px 0 0;padding:7px 0 0}.extra{display:block;padding:8px 10px;font-size:11px;border-radius:5px}.extra:hover{background:var(--nav-hover)}.info-panel{width:190px}::slotted(a),::slotted(button){display:block!important;width:100%!important;padding:10px!important;margin:0!important;border:0!important;background:transparent!important;color:var(--nav-ink)!important;text-align:left!important;font:12px/1.5 -apple-system,BlinkMacSystemFont,'Segoe UI','Microsoft YaHei',sans-serif!important;text-decoration:none!important;cursor:pointer!important;border-radius:5px!important}::slotted(a:hover),::slotted(button:hover){background:var(--nav-hover)!important}
 @media(max-width:540px){nav{gap:5px}nav>.home,summary{font-size:11px;padding:8px 9px}.panel{position:fixed;right:16px;top:var(--panel-top,110px);max-height:calc(100dvh - var(--panel-top,110px) - 16px);overflow-y:auto}.info-panel{width:190px}}
 </style><nav aria-label="全站导航"><a class="home" href="https://jingsong-wang.github.io/">作者主页 ↗</a><details id="projects"><summary>全部项目</summary><div class="panel"><div class="label">JINGSONG WANG / PLAYABLE LABS</div>${projects.map(([id,title,desc,url])=>`<a class="project" href="${url}" ${current===id?'aria-current="'+(page===id?'page':'location')+'"':''}><span class="title">${title}${current===id?'<span class="current">当前项目</span>':''}</span><small>${desc}</small></a>`).join('')}<div class="extras"><a class="extra" href="https://jingsong-wang.github.io/reward-lab/workshop.html" ${page==='workshop'?'aria-current="page"':''}>↳ 机器人创意工坊${page==='workshop'?' · 当前页面':''}</a><a class="extra" href="https://jingsong-wang.github.io/fruit-fly/" ${page==='pong'?'aria-current="page"':''}>↳ 果蝇 Pong 实验${page==='pong'?' · 当前页面':''}</a></div></div></details><details id="info"><summary class="info" aria-label="项目信息" title="项目信息">•••</summary><div class="panel info-panel"><div class="label">项目信息</div><slot name="info"></slot></div></details></nav>`;
 const close=()=>root.querySelectorAll('details[open]').forEach(d=>d.open=false);
 const place=()=>this.style.setProperty('--panel-top',Math.min(this.getBoundingClientRect().bottom+10,innerHeight-100)+'px');
 root.querySelectorAll('summary').forEach(s=>s.addEventListener('click',()=>{place();root.querySelectorAll('details').forEach(d=>{if(d!==s.parentElement)d.open=false;});}));
 root.addEventListener('keydown',e=>{e.stopPropagation();if(e.key==='Escape'){const open=root.querySelector('details[open]');if(open){e.preventDefault();open.open=false;open.querySelector('summary').focus();}}});
 root.addEventListener('click',e=>{if(e.target.closest?.('a'))close();});
 this.addEventListener('click',e=>{if(e.target.closest('a'))close();if(e.target.closest('button')){const dialog=document.querySelector('dialog[open]');if(dialog){close();dialog.addEventListener('close',()=>root.querySelector('#info summary').focus(),{once:true});}}});
 this.abort=new AbortController();document.addEventListener('pointerdown',e=>{if(!e.composedPath().includes(this))close();},{signal:this.abort.signal});window.addEventListener('resize',place,{signal:this.abort.signal});window.addEventListener('scroll',place,{signal:this.abort.signal,passive:true});
 }
 disconnectedCallback(){this.abort?.abort();}
}
customElements.define('lab-navigation',LabNavigation);
